## Why This Is Asked

Tests practical CGOA callback patterns, cross-thread safety, and resource lifecycles in a realistic binding.

## Key Concepts

- CGO callbacks and //export semantics
- Cross-language context/pointer safety
- Synchronization between C threads and Go schedulers
- Lifecycle: registration, unbinding, and resource cleanup

## Code Example

```c
// header: cgobind.h
typedef void (*event_cb)(int event, void* ctx);
void register_event_source(event_cb cb, void* ctx);
void emit_event(int event);
```

```c
// minimal cgobind.c
#include "cgobind.h"
static event_cb g_cb = NULL;
static void* g_ctx = NULL;

void register_event_source(event_cb cb, void* ctx) {
  g_cb = cb;
  g_ctx = ctx;
}

void emit_event(int event) {
  if (g_cb) g_cb(event, g_ctx);
}
```

```go
// binding.go (sketch)
package cgobind

// #cgo CFLAGS: -I.
// #include "cgobind.h"
import "C"
import (
  "sync"
  "unsafe"
)

type EventHandler func(int)

var (
  mu       sync.Mutex
  handles  = make(map[uintptr]EventHandler)
  nextID   uintptr = 1
)

//export goEventCallback
func goEventCallback(ctx unsafe.Pointer, event C.int) {
  id := uintptr(uintptr(ctx))
  mu.Lock()
  h, ok := handles[id]
  mu.Unlock()
  if ok {
    h(int(event))
  }
}

func BindEventHandler(handler EventHandler) (func(), error) {
  mu.Lock()
  id := nextID
  nextID++
  handles[id] = handler
  mu.Unlock()

  // register C callback with context as id
  C.register_event_source((C.event_cb)(C.goEventCallback), unsafe.Pointer(uintptr(id)))

  unbind := func() {
    mu.Lock()
    delete(handles, id)
    mu.Unlock()
  }
  return unbind, nil
}
```

